def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Counts
    opp_c = 0
    opp_d = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
        else:
            opp_d += 1

    last_me, last_opp = history[-1]

    # Near-perfect cooperator: keep cooperating, exploit only in final round.
    if opp_d == 0:
        if n >= 99:
            return 'D'
        return 'C'

    remaining = 100 - n

    # Pure/sustained defector: defect but occasionally probe.
    if opp_c <= 1 and n >= 8:
        if n % 13 == 0:
            return 'C'
        return 'D'

    # Recent window
    look = 10 if n >= 10 else n
    recent_d = 0
    for i in range(n - look, n):
        if history[i][1] == 'D':
            recent_d += 1
    recent_rate = (look - recent_d) / look

    # Defection-heavy opponent overall -> punish hard
    if n >= 12 and opp_d * 2 > n:
        if recent_d >= 4:
            return 'D'
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # Very recent defection burst -> retaliate / lock down
    if recent_d >= 4:
        return 'D'
    if recent_d >= 2:
        # Suspect exploitation; defect mostly but allow restart
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Endgame: grab the extra payoff when safe-ish
    if remaining <= 1:
        return 'D'
    if remaining <= 3:
        if recent_rate >= 0.9:
            return 'D'
        return 'C'

    # Opponent just defected
    if last_opp == 'D':
        # If we already retaliated last round and they were mostly cooperative before,
        # offer cooperation to break a spiral.
        if last_me == 'D' and recent_rate >= 0.7:
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        # Otherwise retaliate firmly
        return 'D'

    # Opponent just cooperated: reward with cooperation, probing only rarely
    if recent_rate >= 0.8:
        # occasional probe against a very compliant opponent
        if n >= 20 and n % 17 == 0:
            return 'D'
        return 'C'

    # Mixed regime: cooperate but watch closely
    if recent_rate >= 0.5:
        return 'C'

    # Mostly defecting recently: defect, with rare forgiveness probes
    if rng.random() < 0.1:
        return 'C'
    return 'D'
